    33	function IOURequestStepTag({
    34	    report,
    35	    route: {
    36	        params: {action, orderWeight: rawTagIndex, transactionID, backTo, iouType, reportActionID},
    37	    },
    38	    transaction,
    39	}: IOURequestStepTagProps) {
    40	    const [policy] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY}${report ? report.policyID : '-1'}`);
    41	    const [policyCategories] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY_CATEGORIES}${report ? report.policyID : '-1'}`);
    42	    const [policyTags] = useOnyx(`${ONYXKEYS.COLLECTION.POLICY_TAGS}${report ? report.policyID : '-1'}`);
    43	    let reportID: string | undefined = '-1';
    44	    if (action === CONST.IOU.ACTION.EDIT) {
    45	        reportID = iouType === CONST.IOU.TYPE.SPLIT ? report?.reportID : report?.parentReportID;
    46	    }
    47	    const [reportActions] = useOnyx(`${ONYXKEYS.COLLECTION.REPORT_ACTIONS}${reportID}`, {canEvict: false});
    48	    const session = useSession();
    49	    const styles = useThemeStyles();
    50	    const {translate} = useLocalize();
    51	
    52	    const tagListIndex = Number(rawTagIndex);
    53	    const policyTagListName = PolicyUtils.getTagListName(policyTags, tagListIndex);
    54	
    55	    const isEditing = action === CONST.IOU.ACTION.EDIT;
    56	    const isSplitBill = iouType === CONST.IOU.TYPE.SPLIT;
    57	    const isEditingSplitBill = isEditing && isSplitBill;
    58	    const transactionTag = TransactionUtils.getTag(transaction);
    59	    const tag = TransactionUtils.getTag(transaction, tagListIndex);
    60	    const reportAction = reportActions?.[report?.parentReportActionID ?? reportActionID] ?? null;
    61	    const canEditSplitBill = isSplitBill && reportAction && session?.accountID === reportAction.actorAccountID && TransactionUtils.areRequiredFieldsEmpty(transaction);
    62	    const policyTagLists = useMemo(() => PolicyUtils.getTagLists(policyTags), [policyTags]);
    63	
    64	    const shouldShowTag = transactionTag || OptionsListUtils.hasEnabledTags(policyTagLists);
    65	
    66	    // eslint-disable-next-line rulesdir/no-negated-variables
    67	    const shouldShowNotFoundPage =
    68	        !ReportUtils.isReportInGroupPolicy(report) ||
    69	        (isEditing && (isSplitBill ? !canEditSplitBill : !ReportActionsUtils.isMoneyRequestAction(reportAction) || !ReportUtils.canEditMoneyRequest(reportAction)));
    70	
    71	    const navigateBack = () => {
    72	        Navigation.goBack(backTo);
    73	    };
