    99	            shouldShowNotFoundPage={shouldShowNotFoundPage}
   100	        >
   101	            {!shouldShowTag && (
   102	                <View style={[styles.flex1]}>
   103	                    <WorkspaceEmptyStateSection
   104	                        shouldStyleAsCard={false}
   105	                        icon={Illustrations.EmptyStateExpenses}
   106	                        title={translate('workspace.tags.emptyTags.title')}
   107	                        subtitle={translate('workspace.tags.emptyTags.subtitle')}
   108	                        containerStyle={[styles.flex1, styles.justifyContentCenter]}
   109	                    />
   110	                    {PolicyUtils.isPolicyAdmin(policy) && (
   111	                        <FixedFooter style={[styles.mtAuto, styles.pt5]}>
   112	                            <Button
   113	                                large
   114	                                success
   115	                                style={[styles.w100]}
   116	                                onPress={() =>
   117	                                    Navigation.navigate(
   118	                                        ROUTES.SETTINGS_TAGS_ROOT.getRoute(
   119	                                            policy?.id ?? '-1',
   120	                                            ROUTES.MONEY_REQUEST_STEP_TAG.getRoute(action, iouType, tagListIndex, transactionID, report?.reportID ?? '-1', backTo, reportActionID),
   121	                                        ),
   122	                                    )
   123	                                }
   124	                                text={translate('workspace.tags.editTags')}
   125	                                pressOnEnter
